from fastapi.routing import APIRoute

from dispatch.auth.permissions import PermissionsDependency
import dispatch.case.views as case_views
import dispatch.incident.views as incident_views

WRITE_METHODS = {"POST", "PUT", "PATCH", "DELETE"}

for name, module in [("case", case_views), ("incident", incident_views)]:
    for route in module.router.routes:
        if not isinstance(route, APIRoute):
            continue
        methods = route.methods & WRITE_METHODS
        if not methods:
            continue
        protected = any(
            isinstance(dependency.call, PermissionsDependency)
            for dependency in route.dependant.dependencies
        )
        status = "PROTECTED" if protected else "UNPROTECTED"
        print(name, sorted(methods), route.path, route.endpoint.__name__, status)

